import {CONSTELLATIONS,STARS,hasStar,prerequisites,constellationBonuses,BONUS_LABELS,evolutionQuote,canReevolve} from './model.js';
const byId=new Map(STARS.map(star=>[star.id,star]));
const status=(s,star)=>hasStar(s,star.id)?'owned':prerequisites(star).some(id=>!hasStar(s,id))?'locked':s.meta.revolutions&&s.meta.insight>=star.cost?'available':'unaffordable';
const progress=(s,sign)=>sign.stars.filter(star=>hasStar(s,star.id)).length;
const number=n=>Math.round(n*1000)/10;
function figure(s,sign,{mini=false,selected='' }={}){
 const points=mini?sign.anchors:sign.stars.map(star=>[star.x,star.y]);
 const lines=sign.edges.map(([a,b])=>'<path class="zodiac-line '+(hasStar(s,sign.stars[a].id)&&hasStar(s,sign.stars[b].id)?'lit':'')+'" d="M'+points[a].join(' ')+' L'+points[b].join(' ')+'"/>').join('');
 const nodes=sign.stars.map((star,i)=>{const [x,y]=points[i],state=status(s,star),label=sign.name+' · '+star.name+' · '+(state==='owned'?'owned':star.cost+' EP, '+state);
  return '<g class="zodiac-node '+state+' '+(star.major?'major':'')+' '+(star.id===selected?'selected':'')+'" transform="translate('+x+' '+y+')" data-star="'+star.id+'" tabindex="0" role="button" aria-label="'+label+'" aria-pressed="'+(star.id===selected)+'"><title>'+label+'</title><circle class="node-hit" r="'+(mini?19:27)+'"/>'+(star.major&&!mini?'<path class="node-rim" d="M0-25L25 0 0 25-25 0Z"/>':'<circle class="node-rim" r="'+(mini?11:22)+'"/>')+'<path class="node-spark" d="M0-8L2-2 8 0 2 2 0 8-2 2-8 0-2-2Z"/>'+(!mini?'<text class="node-index" y="4">'+String(i+1).padStart(2,'0')+'</text><text class="node-cost" y="43">'+(state==='owned'?'Owned':star.cost+' EP')+'</text>':'')+'</g>';
 }).join('');return lines+nodes;
}
function atlas(s,selected){
 let content='<ellipse class="zodiac-orbit" cx="1200" cy="900" rx="850" ry="600"/><ellipse class="zodiac-orbit inner" cx="1200" cy="900" rx="385" ry="280"/>';
 for(let i=0;i<12;i++){
  const sign=CONSTELLATIONS[i],a=(-105+i*30)*Math.PI/180,cx=1200+Math.cos(a)*850,cy=900+Math.sin(a)*600,root=sign.anchors[0],rx=cx+(root[0]-450)*.44,ry=cy+(root[1]-300)*.44;
  content+='<path class="zodiac-spoke '+(progress(s,sign)?'lit':'')+'" d="M'+(1200+Math.cos(a)*170)+' '+(900+Math.sin(a)*170)+'L'+rx+' '+ry+'"/>';
  content+='<g transform="translate('+(cx-198)+' '+(cy-132)+') scale(.44)">'+figure(s,sign,{mini:true,selected})+'</g>';
  content+='<g class="atlas-sign" role="button" tabindex="0" data-sign="'+sign.id+'" aria-label="Explore '+sign.name+'"><rect x="'+(cx-160)+'" y="'+(cy-175)+'" width="320" height="60" rx="10"/><text class="atlas-sign-name" x="'+cx+'" y="'+(cy-137)+'">'+sign.glyph+' '+sign.name+'</text><text class="atlas-count" x="'+cx+'" y="'+(cy+150)+'">'+progress(s,sign)+' / '+sign.stars.length+' stars</text></g>';
 }
 return '<svg class="zodiac-svg atlas-svg" viewBox="0 0 2400 1800" role="group" aria-label="Complete zodiac tree, twelve connected constellations and 147 upgrade stars">'+content+'<circle class="zodiac-core" cx="1200" cy="900" r="170"/><text class="core-symbol" x="1200" y="865">✧</text><text class="core-title" x="1200" y="931">RE-EVOLUTION</text><text class="core-count" x="1200" y="975">'+s.meta.stars.length+' / '+STARS.length+' stars</text></svg>';
}
export function zodiacHTML(s,selected,{view='atlas',zoom=1}={}){
 const star=byId.get(selected)||byId.get('seed'),sign=CONSTELLATIONS.find(c=>c.id===star.sign),owned=hasStar(s,star.id),missing=prerequisites(star).filter(id=>!hasStar(s,id)),available=s.meta.revolutions&&!owned&&!missing.length&&s.meta.insight>=star.cost&&!s.paused,mastered=constellationBonuses(s).masteries.includes(sign.id),n=progress(s,sign);
 const allBonuses=constellationBonuses(s);
 return '<h1 class="page-title">RE-Evolution</h1><section class="zodiac-shell"><header class="zodiac-heading"><div><p class="sky-eyebrow">PERMANENT EVOLUTION</p><h2>The zodiac</h2><p>12 constellations. 147 stars. Choose your path.</p></div><div class="ep-balance"><strong>'+s.meta.insight+'</strong><span>Evolution Points</span></div></header>'+
 (s.meta.pendingEvolution?'<button class="reward-replay" data-evolution-reveal>View Evolution rewards</button>':'')+
 '<div class="zodiac-progress"><span>'+s.meta.stars.length+' / '+STARS.length+' stars owned</span><span>'+allBonuses.masteries.length+' / 12 signs mastered</span></div>'+
 '<nav class="zodiac-signs" aria-label="Zodiac signs">'+CONSTELLATIONS.map(c=>'<button data-sign="'+c.id+'" class="'+(view==='sign'&&c.id===sign.id?'active':'')+'" aria-pressed="'+(view==='sign'&&c.id===sign.id)+'"><span class="sign-glyph" aria-hidden="true">'+c.glyph+'</span><span>'+c.name+'<small>'+progress(s,c)+' / '+c.stars.length+'</small></span></button>').join('')+'</nav>'+
 '<label class="zodiac-mobile-select">Constellation<select id="zodiac-sign"><option value="atlas" '+(view==='atlas'?'selected':'')+'>All twelve signs</option>'+CONSTELLATIONS.map(c=>'<option value="'+c.id+'" '+(view==='sign'&&c.id===sign.id?'selected':'')+'>'+c.glyph+' '+c.name+' · '+progress(s,c)+'/'+c.stars.length+'</option>').join('')+'</select></label>'+
 '<div class="zodiac-workspace"><div class="zodiac-map-panel"><div class="zodiac-toolbar"><div><button data-zodiac-view="atlas" aria-pressed="'+(view==='atlas')+'">Full tree</button><button data-zodiac-view="sign" aria-pressed="'+(view==='sign')+'">'+sign.glyph+' '+sign.name+'</button></div><div class="zodiac-zoom" aria-label="Tree zoom"><button data-zodiac-zoom="-1" aria-label="Zoom out of zodiac tree" '+(zoom<=.75?'disabled':'')+'>−</button><output>'+Math.round(zoom*100)+'%</output><button data-zodiac-zoom="1" aria-label="Zoom into zodiac tree" '+(zoom>=3?'disabled':'')+'>+</button></div></div>'+
 (view==='sign'?'<header class="zodiac-sign-heading"><div><span aria-hidden="true">'+sign.glyph+'</span><div><h3>'+sign.name+' <small>'+sign.title+'</small></h3><p>'+sign.subtitle+'</p></div></div><strong>'+n+' / '+sign.stars.length+'</strong></header>':'')+
 '<div id="zodiac-canvas" class="zodiac-canvas '+(view==='atlas'?'atlas-canvas':'sign-canvas')+'" tabindex="0" aria-label="Scrollable zodiac star tree"><div class="zodiac-drawing" style="width:'+(view==='atlas'?(zoom*100)+'%':(900*zoom)+'px')+'">'+(view==='atlas'?atlas(s,star.id):'<svg class="zodiac-svg sign-svg" viewBox="0 0 900 600" role="group" aria-label="'+sign.name+' constellation upgrade tree">'+figure(s,sign,{selected:star.id})+'</svg>')+'</div></div>'+
 '<div class="zodiac-map-footer"><span><i class="legend-dot owned"></i>Owned</span><span><i class="legend-dot available"></i>Affordable</span><span><i class="legend-dot locked"></i>Locked</span><span>Drag scrollbars or swipe to explore</span></div>'+
 (view==='sign'?'<div class="zodiac-mastery '+(mastered?'mastered':'')+'"><strong>'+sign.glyph+' '+sign.name+' mastery '+(mastered?'· Active':'· '+n+'/'+sign.stars.length)+'</strong><p>'+sign.masteryDescription+'</p><small>'+(mastered?'Permanent mastery bonus active.':'Own every star in this sign to gain this bonus automatically.')+'</small></div>':'<p class="zodiac-atlas-help">Choose a sign to explore its branching stars. Select a star to preview its bonus before buying.</p>')+'</div>'+
 '<aside class="zodiac-detail" aria-live="polite"><p class="sky-eyebrow">'+sign.glyph+' '+sign.name.toUpperCase()+' · STAR '+String(sign.stars.indexOf(star)+1).padStart(2,'0')+'</p><h3>'+star.name+'</h3><p class="zodiac-star-kind">'+(star.major?'Keystone star':'Permanent bonus')+'</p><p class="zodiac-effect">'+star.description+'</p>'+
 (missing.length?'<div class="zodiac-prerequisites"><span>Requires</span>'+missing.map(id=>'<button data-star="'+id+'">'+byId.get(id).name+' <span aria-hidden="true">↗</span></button>').join('')+'</div>':!owned?'<p class="zodiac-requirement">'+(!s.meta.revolutions?'Complete your first RE-Evolution.':s.meta.insight<star.cost?'Need '+(star.cost-s.meta.insight)+' more EP.':'This path is open.')+'</p>':'')+
 '<button class="star-buy" data-buy-star="'+star.id+'" '+(!available?'disabled':'')+'>'+(owned?'Star owned':'Buy star · '+star.cost+' EP')+'</button>'+
 (view==='atlas'?'<button class="zodiac-explore" data-sign="'+sign.id+'">Explore '+sign.name+' →</button>':'')+
 '<label class="zodiac-node-select">Select a star<select id="zodiac-star">'+sign.stars.map((x,i)=>'<option value="'+x.id+'" '+(x.id===star.id?'selected':'')+'>'+String(i+1).padStart(2,'0')+' · '+x.name+' · '+(hasStar(s,x.id)?'Owned':x.cost+' EP')+'</option>').join('')+'</select></label><p class="zodiac-spending-help">Bonuses stay active through every reset. Points are spent only when you press Buy star.</p></aside></div>'+
 '<details class="zodiac-bonus-summary"><summary>Active permanent bonuses · '+s.meta.stars.length+' stars</summary><div>'+STARS.filter(x=>hasStar(s,x.id)&&!Object.keys(x.effects).length).map(x=>'<p><strong>'+x.name+'</strong> '+x.description+'</p>').join('')+Object.entries(allBonuses.bonuses).map(([key,value])=>'<p><strong>'+(key==='foodUse'?'−':'+')+number(value)+'%</strong> '+(key==='foodUse'?'resident food consumption':BONUS_LABELS[key])+'</p>').join('')+(s.meta.stars.length?'':'<p>No stars purchased yet.</p>')+'</div></details><footer class="zodiac-credits"><a href="./credits.html" target="_blank" rel="noopener noreferrer">Constellation pattern credits ↗</a></footer></section>'+
 '<section class="evolution-next"><h2>Evolution '+(s.meta.revolutions+1)+' · '+(s.meta.revolutions?'The Renaissance':'The first observation')+'</h2><p>'+(s.meta.revolutions?'Guild specializations, Renaissance research and the Celestial Atlas are available in this civilization.':'Complete the Great Observatory to earn Evolution Points and unlock the next civilization.')+'</p>'+(canReevolve(s)?'<button class="primary" data-reevolve>Review RE-Evolution · '+evolutionQuote(s).total+' EP</button>':'')+'</section>'+
 (Object.values(s.meta.upgrades).some(Boolean)?'<p class="worker-help">Your earlier production, storage and research upgrades are still active.</p>':'')+
 '<h2 class="run-history-heading">Completed civilizations</h2>'+(s.meta.history.length?s.meta.history.map(h=>'<div class="run-history-row"><span>Civilization '+h.run+'</span><span>'+Math.floor(h.seconds/3600)+'h '+Math.floor(h.seconds/60%60)+'m · +'+h.reward+' '+(h.currency==='EP'?'EP':'legacy Insight')+'</span></div>').join(''):'<p class="worker-help">Your first completed civilization will appear here.</p>');
}
